import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5c2');scene.fog=new THREE.FogExp2('#a9c5c2',.0065);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,500);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#e4f0e2','#586651',2.1));const sun=new THREE.DirectionalLight('#fff0ce',3.1);sun.position.set(-45,85,40);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-115;sun.shadow.camera.right=115;sun.shadow.camera.top=115;sun.shadow.camera.bottom=-115;sun.shadow.bias=-.0003;scene.add(sun);
const mats={grass:new THREE.MeshStandardMaterial({color:'#718c5f',roughness:1}),grass2:new THREE.MeshStandardMaterial({color:'#829768',roughness:1}),earth:new THREE.MeshStandardMaterial({color:'#665846',roughness:1}),road:new THREE.MeshStandardMaterial({color:'#9b8a69',roughness:1}),asphalt:new THREE.MeshStandardMaterial({color:'#515a55',roughness:.95}),railbed:new THREE.MeshStandardMaterial({color:'#5d5145',roughness:1}),rail:new THREE.MeshStandardMaterial({color:'#9ca4a0',metalness:.7,roughness:.38}),wood:new THREE.MeshStandardMaterial({color:'#72583c',roughness:1}),trunk:new THREE.MeshStandardMaterial({color:'#5e4936',roughness:1}),leaf:new THREE.MeshStandardMaterial({color:'#496b4d',roughness:1}),leaf2:new THREE.MeshStandardMaterial({color:'#708a53',roughness:1}),roof:new THREE.MeshStandardMaterial({color:'#923f33',roughness:.9}),roof2:new THREE.MeshStandardMaterial({color:'#53615a',roughness:.9}),plaster:new THREE.MeshStandardMaterial({color:'#d2c4a0',roughness:.95}),blue:new THREE.MeshStandardMaterial({color:'#72939a',roughness:.9}),cream:new THREE.MeshStandardMaterial({color:'#d3c8ae',roughness:.9}),window:new THREE.MeshStandardMaterial({color:'#9cc2c3',roughness:.35,metalness:.12}),dark:new THREE.MeshStandardMaterial({color:'#283331',roughness:.85}),water:new THREE.MeshStandardMaterial({color:'#568b91',roughness:.25,metalness:.1,transparent:true,opacity:.88}),snow:new THREE.MeshStandardMaterial({color:'#dbe3da',roughness:1})};
const boxGeo=new THREE.BoxGeometry(1,1,1);const cylGeo=new THREE.CylinderGeometry(.5,.5,1,8);const sphereGeo=new THREE.SphereGeometry(1,10,8);
function box(parent,x,y,z,sx,sy,sz,mat,cast=true){const m=new THREE.Mesh(boxGeo,mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,mat,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function group(parent=scene){const g=new THREE.Group();parent.add(g);return g}
function hash(x,z){const v=Math.sin(x*127.1+z*311.7)*43758.5453;return v-Math.floor(v)}
function terrainHeight(x,z){return Math.sin(x*.038)*1.5+Math.cos(z*.045)*1.25+Math.sin((x+z)*.021)*2.1+Math.cos((x-z)*.016)*1.1+Math.sin(x*.13+z*.08)*.24}
function groundColor(x,z){const d=Math.hypot(x,z);if(d>90)return '#67816e';if(x>42&&z<-28)return '#789483';if(z>42&&x<-30)return '#7e9065';return hash(Math.floor(x/4),Math.floor(z/4))>.82?'#788e63':'#70885e'}
const landGeo=new THREE.PlaneGeometry(230,230,100,100);landGeo.rotateX(-Math.PI/2);const p=landGeo.attributes.position;const colors=[];const c=new THREE.Color();for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);p.setY(i,terrainHeight(x,z)-.35);c.set(groundColor(x,z));colors.push(c.r,c.g,c.b)}landGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));landGeo.computeVertexNormals();const landMat=new THREE.MeshStandardMaterial({vertexColors:true,roughness:1});const land=new THREE.Mesh(landGeo,landMat);land.receiveShadow=true;scene.add(land);
// distant spruce ridges
for(let i=0;i<60;i++){let a=hash(i,8)*Math.PI*2,r=96+hash(i,19)*30,x=Math.cos(a)*r,z=Math.sin(a)*r;const h=10+hash(i,21)*18;const g=group();g.position.set(x,terrainHeight(x,z),z);cylinder(g,0,h*.32,0,.8,.55,h*.64,mats.trunk,7);for(let n=0;n<3;n++)cylinder(g,0,h*(.42+n*.2),0,h*(.34-n*.08),0,h*.46,n%2?mats.leaf2:mats.leaf,7)}
// river winding across eastern lowland
const riverPts=[];for(let i=0;i<=30;i++){const z=-105+i*7;riverPts.push(new THREE.Vector3(50+Math.sin(i*.4)*8,terrainHeight(50,z)-.15,z))}const river=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(riverPts),100,4.2,8,false),mats.water);river.receiveShadow=true;scene.add(river);
// little crossing bridge
const bridge=group();bridge.position.set(50,terrainHeight(50,0)+.7,0);box(bridge,0,0,0,13,.65,9,mats.wood);for(let side of [-1,1])for(let x=-5;x<=5;x+=2)box(bridge,x,.55,side*4.2,.35,1.1,.35,mats.wood);
// track sections, rails are twin bars and ties
const railSegments=[];function addRailLine(points,materialize=true){const curve=new THREE.CatmullRomCurve3(points);const length=curve.getLength();const groupRail=group();groupRail.userData={curve,length};const samples=Math.max(2,Math.floor(length/2.5));for(let i=0;i<=samples;i++){const t=i/samples,pos=curve.getPointAt(t);const tan=curve.getTangentAt(t);const angle=Math.atan2(tan.x,tan.z);const tie=box(groupRail,pos.x,terrainHeight(pos.x,pos.z)+.1,pos.z,2.4,.22,.33,mats.wood);tie.rotation.y=angle;for(const side of [-.72,.72]){const off=new THREE.Vector3(side,0,0).applyAxisAngle(new THREE.Vector3(0,1,0),angle);const rail=box(groupRail,pos.x+off.x,terrainHeight(pos.x,pos.z)+.35,pos.z+off.z,.16,.17,2.5,mats.rail);rail.rotation.y=angle}}
railSegments.push({curve,length,group:groupRail,kind:'rail'});return {curve,length,group:groupRail}}
const villageRail=addRailLine([new THREE.Vector3(-45,0,13),new THREE.Vector3(-33,0,12),new THREE.Vector3(-20,0,9),new THREE.Vector3(-4,0,7),new THREE.Vector3(11,0,4),new THREE.Vector3(25,0,0),new THREE.Vector3(40,0,-2)]);
// station and freight depot
const station=group();station.position.set(-16,terrainHeight(-16,11),11);box(station,0,1.4,0,12,2.8,5.8,mats.cream);box(station,0,3,-.05,12.7,.5,6.4,mats.roof);box(station,0,4.15,-.05,8.8,.12,3.8,mats.roof2);for(let x=-4;x<=4;x+=2.7){box(station,x,1.4,2.92,1.1,1.25,.08,mats.window);box(station,x,2.08,2.98,1.2,.12,.15,mats.wood)}box(station,-.4,2.38,3.04,4.2,.15,.15,mats.wood);box(station,0,.27,4.2,16,.22,4,mats.wood);for(let x=-7;x<=7;x+=1.3)box(station,x,.27,5.9,.12,.95,.12,mats.wood);box(station,0,2.25,3.15,3,.18,.18,mats.wood);
const depot=group();depot.position.set(-35,terrainHeight(-35,20),20);box(depot,0,2,0,10,4,8,mats.blue);box(depot,0,4.15,0,10.6,.5,8.6,mats.roof2);box(depot,0,1.5,4.05,5,2.7,.16,mats.dark);box(depot,-5.15,2,0,.45,4,.45,mats.wood);box(depot,5.15,2,0,.45,4,.45,mats.wood);
// buildings and small neighborhood
const houses=[];function house(x,z,type=0,scale=1){const g=group();g.position.set(x,terrainHeight(x,z),z);const width=(5+hash(x,z)*1.8)*scale,depth=(4.5+hash(z,x)*1.4)*scale,h=(2.7+hash(x+2,z)*.55)*scale;const wall=[mats.plaster,mats.blue,mats.cream][type%3],roofMat=type===1?mats.roof2:mats.roof;box(g,0,h/2,0,width,h,depth,wall);const roofMesh=box(g,0,h+.43,0,width+1,.75,depth+1,roofMat);roofMesh.rotation.z=.03;box(g,0,h+.85,0,width*.54,.5,depth+1.05,roofMat);for(let side of [-1,1])box(g,side*width*.24,h*.62,depth/2+.055,.65,.82,.08,mats.window);box(g,0,.92,depth/2+.06,.8,1.75,.12,mats.wood);box(g,0,h+1.05,0,.6,.35,.55,mats.roof2);g.userData={kind:'house',x,z,scale};houses.push(g);return g}
const positions=[[-27,-2],[-29,-11],[-20,-15],[-9,-15],[1,-13],[9,-11],[13,-4],[4,14],[-7,19],[-21,15],[-29,11],[17,12],[23,17]];positions.forEach((v,i)=>house(v[0],v[1],i%3));
// newer apartment blocks on the far edge
function apartment(x,z){const g=group();g.position.set(x,terrainHeight(x,z),z);box(g,0,5,0,8,10,7,mats.cream);box(g,0,10.25,0,8.5,.5,7.5,mats.roof2);for(let y=2;y<9;y+=2)for(let xw=-2.6;xw<=2.6;xw+=1.3)box(g,xw,y,3.55,.65,1.05,.08,mats.window);box(g,0,1,3.62,1,1.9,.12,mats.wood);g.visible=false;g.userData.kind='upgrade';houses.push(g);return g}
const newBlocks=[apartment(20,-19),apartment(28,-16)];
// village road, initially dirt
function path(points,width,mat){const curve=new THREE.CatmullRomCurve3(points.map(([x,z])=>new THREE.Vector3(x,terrainHeight(x,z)+.04,z)));const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,Math.max(30,points.length*10),width/2,6,false),mat);mesh.scale.y=.09;mesh.receiveShadow=true;scene.add(mesh);return mesh}
const villagePath=path([[-35,8],[-22,4],[-14,-3],[-1,-5],[12,-2],[21,5],[25,15]],5,mats.road);const sidePath=path([[-17,-2],[-18,-9],[-13,-16],[-6,-20]],3,mats.road);const toStation=path([[-20,4],[-19,8],[-16,11]],3,mats.road);
// trees, boulders, grasses
function tree(x,z,size=1,leafMat=mats.leaf){const y=terrainHeight(x,z);const g=group();g.position.set(x,y,z);const h=(3.3+hash(x,z)*1.8)*size;cylinder(g,0,h*.32,0,.2*size,.13*size,h*.65,mats.trunk,7);for(let i=0;i<3;i++){const canopy=cylinder(g,0,h*(.42+i*.18),0,(1.25-i*.23)*size,.05*size,h*.55,leafMat,8);canopy.rotation.y=hash(i,x)*.8}return g}
for(let i=0;i<185;i++){let x=(hash(i,44)-.5)*175,z=(hash(i,88)-.5)*175;if(Math.hypot(x,z)<35||Math.abs(x-50)<9)continue;tree(x,z,.65+hash(i,32)*.65,hash(i,99)>.55?mats.leaf:mats.leaf2)}
for(let i=0;i<38;i++){const x=(hash(i,140)-.5)*115,z=(hash(i,152)-.5)*100;if(Math.hypot(x,z)<30)continue;const rock= new THREE.Mesh(new THREE.DodecahedronGeometry(.6+hash(i,199)*1.5,0),new THREE.MeshStandardMaterial({color:hash(i,200)>.5?'#777b6e':'#888478',roughness:1}));rock.position.set(x,terrainHeight(x,z)+.3,z);rock.scale.y=.55;rock.castShadow=true;scene.add(rock)}
// village people: simple colorful 3d neighbors
const villagers=[];const personMats=['#b85c41','#4e7778','#d0b767','#6a7194','#b4c39a'].map(c=>new THREE.MeshStandardMaterial({color:c,roughness:.8}));function villager(x,z){const g=group();g.position.set(x,terrainHeight(x,z),z);const body=new THREE.Mesh(cylGeo,personMats[Math.floor(hash(x,z)*personMats.length)]);body.position.y=.95;body.scale.set(.42,.85,.35);body.castShadow=true;g.add(body);const head=new THREE.Mesh(sphereGeo,mats.cream);head.position.y=1.55;head.scale.set(.28,.31,.28);head.castShadow=true;g.add(head);g.userData={x,z,phase:hash(z,x)*6,homeX:x,homeZ:z};villagers.push(g)}
for(let i=0;i<12;i++)villager(-26+hash(i,220)*42,-14+hash(i,221)*30);
// low shrubs add depth near paths
for(let i=0;i<130;i++){const x=(hash(i,300)-.5)*75,z=(hash(i,301)-.5)*65;if(Math.hypot(x,z)<33)continue;const shrub=new THREE.Mesh(sphereGeo,mats.leaf2);shrub.position.set(x,terrainHeight(x,z)+.3,z);shrub.scale.set(.45,.32,.5);scene.add(shrub)}
// player
const player=group();const coat=new THREE.Mesh(cylGeo,new THREE.MeshStandardMaterial({color:'#d5b879',roughness:.8}));coat.position.y=.95;coat.scale.set(.48,.9,.42);coat.castShadow=true;player.add(coat);const head=new THREE.Mesh(sphereGeo,mats.cream);head.position.y=1.58;head.scale.set(.3,.34,.3);head.castShadow=true;player.add(head);const backpack=box(player,0,1.05,-.3,.46,.6,.24,mats.wood);player.position.set(-7,terrainHeight(-7,3),3);

// Russian-inspired electric commuter train and freight consist, moving on the valley railway.
const trains=[];function makeTrain(kind){const g=group();const loco=kind==='freight';const bodyMat=new THREE.MeshStandardMaterial({color:loco?'#496d61':'#779c9a',roughness:.48,metalness:.18});const stripe=new THREE.MeshStandardMaterial({color:loco?'#d4b649':'#e6d9bb',roughness:.55});const carCount=loco?5:2;for(let i=0;i<carCount;i++){const car=group(g);const isEngine=i===0;box(car,0,1.3,0,isEngine?8.2:7.6,2.4,2.7,isEngine&&loco?new THREE.MeshStandardMaterial({color:'#3c564d',roughness:.55}):bodyMat);box(car,0,2.58,0,isEngine?7.3:7.4,.18,2.45,mats.dark);for(let wx=-2.8;wx<=2.81;wx+=1.35){box(car,wx,1.76,1.37,.85,.82,.08,mats.window);box(car,wx,1.76,-1.37,.85,.82,.08,mats.window)}box(car,0,.82,0,isEngine&&loco?3.5:5.8,.18,2.95,mats.dark);box(car,0,.92,1.4,isEngine&&loco?5.8:6.5,.12,.08,stripe);for(const xx of [-2.4,2.4])for(const side of [-1,1]){const wheel=new THREE.Mesh(cylGeo,mats.dark);wheel.rotation.z=Math.PI/2;wheel.scale.set(.31,.22,.31);wheel.position.set(xx,.53,side*1.35);car.add(wheel)}if(isEngine){box(car,0,.96,1.41,1.1,.42,.09,stripe);box(car,0,1.7,1.43,1.2,.65,.1,bodyMat)}car.position.z=-i*8.15}
const pantograph=group(g);for(const side of [-1,1]){const p1=box(pantograph,0,3.2,side*2.7,.12,1.1,.12,mats.dark);p1.rotation.z=.45;box(pantograph,0,3.72,side*2.7,1.25,.12,.12,mats.dark)}
if(loco){box(g,0,2.7,0,3.5,.35,2.8,new THREE.MeshStandardMaterial({color:'#364640',roughness:.6}));for(let i=1;i<carCount;i++){const freight=group(g);freight.position.z=-i*8.15;box(freight,0,1.1,0,7.4,1.5,2.6,new THREE.MeshStandardMaterial({color:i%2?'#80654b':'#986c4c',roughness:.95}));box(freight,0,1.88,0,7.5,.15,2.7,mats.dark);for(let x=-3;x<=3;x+=1.5)box(freight,x,1.15,1.31,.1,1.45,.12,mats.wood)}}
scene.add(g);const obj={group:g,kind,progress:kind==='commuter'?.1:0,speed:kind==='commuter'?.045:0,active:kind==='commuter'};trains.push(obj);return obj}
const commuter=makeTrain('commuter');const freightTrain=makeTrain('freight');freightTrain.group.visible=false;
// distant villages: tiny skyline landmarks, connected only after a construction project
const farVillage=group();farVillage.position.set(69,terrainHeight(69,-14),-14);for(let i=0;i<7;i++){const x=(i%3)*5-5,z=Math.floor(i/3)*5-5;house(0,0,i%3,.53);const h=new THREE.Mesh(boxGeo,mats.cream);h.position.set(x,1.1,z);h.scale.set(3.2,2.2,3);farVillage.add(h);const r=new THREE.Mesh(boxGeo,i%2?mats.roof:mats.roof2);r.position.set(x,2.35,z);r.scale.set(3.4,.45,3.2);farVillage.add(r)}
// caves as shadowed hillside entrances and exposed rock strata, visible beyond the village
function cave(x,z){const g=group();g.position.set(x,terrainHeight(x,z)+.2,z);const rockmat=new THREE.MeshStandardMaterial({color:'#514c43',roughness:1});const arch=new THREE.Mesh(new THREE.TorusGeometry(2.8,.75,7,10,Math.PI),rockmat);arch.rotation.z=Math.PI;arch.position.y=2.2;g.add(arch);const hole=new THREE.Mesh(new THREE.CircleGeometry(2.1,12),new THREE.MeshBasicMaterial({color:'#161b19'}));hole.position.set(0,1.6,.18);g.add(hole);for(let i=0;i<4;i++){const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.22),new THREE.MeshStandardMaterial({color:i%2?'#83b5a3':'#d0a76c',emissive:i%2?'#214536':'#503016',emissiveIntensity:.3}));crystal.position.set(-1.3+i*.8,.5+hash(i,x)*.8,.3);g.add(crystal)}}cave(-56,35);cave(75,38);
// seasonal atmosphere and ambient particles
const rainCount=650,rainGeo=new THREE.BufferGeometry(),rainPositions=new Float32Array(rainCount*3);for(let i=0;i<rainCount;i++){rainPositions[i*3]=(Math.random()-.5)*100;rainPositions[i*3+1]=Math.random()*35;rainPositions[i*3+2]=(Math.random()-.5)*100}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:'#d2e8eb',size:.12,transparent:true,opacity:.65}));rain.visible=false;scene.add(rain);
const snowGeo=new THREE.BufferGeometry(),snowPos=new Float32Array(400*3);for(let i=0;i<400;i++){snowPos[i*3]=(Math.random()-.5)*90;snowPos[i*3+1]=Math.random()*35;snowPos[i*3+2]=(Math.random()-.5)*90}snowGeo.setAttribute('position',new THREE.BufferAttribute(snowPos,3));const snowflakes=new THREE.Points(snowGeo,new THREE.PointsMaterial({color:'#f5fbff',size:.21,transparent:true,opacity:.85}));snowflakes.visible=false;scene.add(snowflakes);
const seasons=['Весна','Лето','Осень','Зима'];let seasonIndex=0,day=1,clockHours=8+40/60,weather='Переменная облачность',mode='walk',resources=74,mood=86,roadLevel=0,delivered=false,connections=0,disasterTimer=0,disasterActive=false,disasterElapsed=0,repairWork=0,gameTime=0;
const $=s=>document.querySelector(s);function say(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>t.classList.remove('show'),2800)}
function setMode(m){mode=m;document.querySelectorAll('.action').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));if(m!=='walk')say(({rail:'Выбрано строительство железной дороги',road:'Выбрано улучшение уличных дорог',supply:'Груз готов к отправке со станции',repair:'Жители ждут помощи у станции'})[m]||'');}
document.querySelectorAll('.action').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));window.addEventListener('keydown',e=>{if(['1','2','3','4'].includes(e.key))setMode(['walk','rail','road','supply'][Number(e.key)-1]);if(e.key.toLowerCase()==='e')interact();if(e.key==='Escape')setMode('walk')});$('#mobileAct').onclick=interact;
function updateHud(){const h=Math.floor(clockHours),mins=Math.floor((clockHours-h)*60);$('#clock').textContent=`${seasonIndex===3?'❄️':seasonIndex===2?'🍂':seasonIndex===1?'☀️':'🌤️'} День ${String(day).padStart(2,'0')} · ${String(h).padStart(2,'0')}:${String(mins).padStart(2,'0')}`;$('#seasonLine').textContent=`${seasons[seasonIndex]} · ${12+connections*3} жителей`;$('#resources').textContent=`▰ ${Math.round(resources)}%` ;$('#mood').textContent=`☺ ${Math.round(mood)}%`;$('#weatherName').textContent=weather;$('#temperature').textContent=`${seasonIndex===3?'-3':seasonIndex===2?'+8':seasonIndex===1?'+22':'+12'}° · ${weather==='Дождь'?'свежий ветер':'лёгкий ветер'}`;$('#weatherIcon').textContent=weather==='Дождь'?'🌧️':weather==='Снегопад'?'🌨️':weather==='Туман'?'🌫️':weather==='Гроза'?'⛈️':seasonIndex===3?'❄️':'🌤️';$('#status').innerHTML=`${roadLevel?'Асфальтовые улицы':'Грунтовые улицы'} · малое депо<br>Соединено с: <b>${connections} ${connections===1?'деревней':'деревнями'}</b>`;}
let nearObject='';function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function nearest(){const targets=[{name:'Пассажирская станция',x:-16,z:11},{name:'Железнодорожное депо',x:-35,z:20},{name:'Грузовая площадка',x:-35,z:20}];return targets.sort((a,b)=>dist(player.position,a)-dist(player.position,b))[0]}
function interact(){const target=nearest();if(dist(player.position,target)<11){if(mode==='supply'||target.name==='Грузовая площадка'){if(!delivered){delivered=true;resources=Math.min(100,resources+18);freightTrain.group.visible=true;freightTrain.active=true;freightTrain.speed=.024;$('#objective').innerHTML='Грузовой состав отправлен. Материалы прибудут в соседнее <b>Новолесье</b>.';say('Грузовой состав ВЛ80 отправился в Новолесье');setTimeout(()=>completeDelivery(),16000)}else say('Груз уже в пути — жители ждут обновления станции')}else if(mode==='repair'){repairVillage();}else{commuter.active=true;say('Электропоезд доехал до станции — добро пожаловать!')}}else if(mode==='rail'){buildRail()}else if(mode==='road'){improveRoad()}else if(mode==='repair'){repairVillage()}else{say('Подойдите к станции или депо, чтобы взаимодействовать')}}
function buildRail(){if(connections){say('Путь до Новолесья уже построен');return}if(resources<18){say('Недостаточно материалов для пути');return}const pts=[new THREE.Vector3(39,0,-2),new THREE.Vector3(48,0,-6),new THREE.Vector3(56,0,-9),new THREE.Vector3(65,0,-13),new THREE.Vector3(75,0,-13)];addRailLine(pts);connections=1;resources-=18;const road=path([[39,-2],[48,-6],[58,-10],[69,-13]],3.2,mats.road);say('Бригада проложила путь к Новолесью. Жители открыли дальний маршрут!');$('#objective').innerHTML='Путь готов. Отправьте грузовой поезд, чтобы запустить <b>рост Новолесья</b>.';updateHud()}
function improveRoad(){if(roadLevel){say('Улицы уже заасфальтированы — отлично!');return}if(resources<12){say('Нужно больше ресурсов с грузовой станции');return}resources-=12;roadLevel=1;scene.remove(villagePath);scene.remove(sidePath);scene.remove(toStation);path([[-35,8],[-22,4],[-14,-3],[-1,-5],[12,-2],[21,5],[25,15]],5,mats.asphalt);path([[-17,-2],[-18,-9],[-13,-16],[-6,-20]],3,mats.asphalt);path([[-20,4],[-19,8],[-16,11]],3,mats.asphalt);for(let i=0;i<5;i++){const car=group();const x=-18+i*8,z=-4+Math.sin(i)*2;car.position.set(x,terrainHeight(x,z)+.35,z);box(car,0,.55,0,2.7,1,1.35,i%2?mats.blue:new THREE.MeshStandardMaterial({color:'#b8b39a',roughness:.65}));box(car,0,1.1,0,1.45,.35,1.2,mats.window);for(let xx of [-.8,.8])for(let zz of [-.7,.7]){const w=new THREE.Mesh(cylGeo,mats.dark);w.rotation.z=Math.PI/2;w.scale.set(.2,.13,.2);w.position.set(xx,.24,zz);car.add(w)}}say('Дорожная бригада уложила асфальт. Появились первые автомобили!');updateHud()}
function repairVillage(){if(!disasterActive){mood=Math.min(100,mood+3);resources=Math.min(100,resources+2);repairWork+=1;villagers.forEach(v=>{v.userData.x+=(v.userData.homeX-v.userData.x)*.18;v.userData.z+=(v.userData.homeZ-v.userData.z)*.18});say(repairWork%3===0?'Жители помогают друг другу и приводят улицы в порядок':'Вы помогли жителям: запасы понемногу восстановлены');updateHud();return}disasterActive=false;$('#event').style.display='none';mood=Math.min(100,mood+14);resources=Math.min(100,resources+6);for(const h of houses)h.rotation.z=0;villagers.forEach(v=>{v.userData.x+=(v.userData.homeX-v.userData.x)*.8;v.userData.z+=(v.userData.homeZ-v.userData.z)*.8});say('Бригада восстановила деревню. Жители уже чинят дома и станцию!');updateHud()}
function completeDelivery(){if(!freightTrain.active)return;freightTrain.active=false;freightTrain.speed=0;newBlocks.forEach(b=>b.visible=true);connections=Math.max(1,connections);mood=Math.min(100,mood+8);resources=Math.min(100,resources+12);$('#objective').innerHTML='Новолесье растёт! Появились <b>панельные дома и новые магазины</b>.';say('Доставка завершена — Новолесье выросло!');updateHud()}

