canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;yaw-=dx*.006;cameraHeight=THREE.MathUtils.clamp(cameraHeight+dy*.06,7,38)});canvas.addEventListener('wheel',e=>{cameraDistance=THREE.MathUtils.clamp(cameraDistance+e.deltaY*.025,18,55)},{passive:true});
window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
document.querySelectorAll('.touchpad button').forEach(button=>{const key={up:'w',down:'s',left:'a',right:'d'}[button.dataset.dir];button.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true});for(const ev of ['pointerup','pointercancel','pointerleave'])button.addEventListener(ev,()=>keys[key]=false)});
function startHazard(){if(disasterActive)return;disasterActive=true;disasterElapsed=0;const events=[['Сильный шторм','Ветер усилился. Жители закрывают окна и проверяют мост.'],['Подъём воды','После ливней вода поднялась у низины. Бригада укрепляет берег.'],['Подземные толчки','Небольшое землетрясение! Жители собрались у станции.']];const event=events[Math.floor(Math.random()*events.length)];$('#event').innerHTML=`⚠️ <b>${event[0]}</b><br>${event[1]}`;$('#event').style.display='block';mood=Math.max(50,mood-7);for(const h of houses){if(h.userData?.kind==='house')h.rotation.z=(Math.random()-.5)*.045}villagers.forEach(v=>{v.userData.x=-16+(Math.random()-.5)*7;v.userData.z=11+(Math.random()-.5)*7});say('Экстренное оповещение: жители действуют сообща');updateHud()}
function changeSeason(){seasonIndex=(seasonIndex+1)%4;const colors=['#a9c5c2','#c0d0bd','#b8b2a1','#b6c8d0'];scene.background.set(colors[seasonIndex]);scene.fog.color.set(colors[seasonIndex]);landMat.color.set(seasonIndex===3?'#dce4dd':'#ffffff');snowflakes.visible=seasonIndex===3&&weather==='Снегопад';weather=seasonIndex===3?'Снегопад':seasonIndex===2?'Туман':'Переменная облачность';say(`Наступил сезон: ${seasons[seasonIndex].toLowerCase()}`);updateHud()}
function advanceClock(dt){clockHours+=dt*.04;if(clockHours>=24){clockHours-=24;day++;resources=Math.min(100,resources+.7)}if(day%4===0&&clockHours<.05)changeSeason();if(Math.random()<dt*.0014){const options=['Дождь','Переменная облачность','Туман','Гроза'];weather=options[Math.floor(Math.random()*options.length)];rain.visible=weather==='Дождь'||weather==='Гроза';if(weather==='Дождь'||weather==='Гроза')say(weather==='Гроза'?'Приближается гроза — жители укрываются в домах':'Начался дождь в долине');updateHud()}if(seasonIndex===3&&weather==='Снегопад')snowflakes.visible=true;if(!disasterActive){disasterTimer+=dt;if(disasterTimer>85){disasterTimer=0;if(Math.random()<.78)startHazard()}}else{disasterElapsed+=dt;if(disasterElapsed>26)repairVillage()}}
function moveTrain(obj,dt){if(!obj.active)return;let route=obj===freightTrain&&longRoute?longRoute:villageRail;if(!route)return;obj.progress+=obj.speed*dt;if(obj.progress>1){obj.progress=0;if(obj===freightTrain&&obj.active&&connections)completeDelivery()}const t=route.curve.getPointAt(obj.progress);const tangent=route.curve.getTangentAt(obj.progress);obj.group.position.set(t.x,terrainHeight(t.x,t.z)+.1,t.z);obj.group.rotation.y=Math.atan2(tangent.x,tangent.z)}
function animateVillagers(t,dt){villagers.forEach((v,i)=>{const u=v.userData;if(disasterActive&&Math.hypot(u.x+16,u.z-11)>2){u.x+=(-16-u.x)*dt*.12;u.z+=(11-u.z)*dt*.12}else if(!disasterActive){u.x=u.homeX+Math.sin(t*.45+u.phase)*1.8;u.z=u.homeZ+Math.cos(t*.39+u.phase)*1.6}v.position.set(u.x,terrainHeight(u.x,u.z),u.z);v.rotation.y=Math.sin(t+u.phase)*.18})}
function playerMove(dt){let f=0,s=0;if(keys.w||keys.arrowup)f+=1;if(keys.s||keys.arrowdown)f-=1;if(keys.a||keys.arrowleft)s-=1;if(keys.d||keys.arrowright)s+=1;if(!f&&!s)return;const len=Math.hypot(f,s);f/=len;s/=len;const speed=10;const dx=(Math.sin(yaw)*f+Math.cos(yaw)*s)*speed*dt,dz=(Math.cos(yaw)*f-Math.sin(yaw)*s)*speed*dt;const nx=player.position.x+dx,nz=player.position.z+dz;if(Math.abs(nx)<105&&Math.abs(nz)<105){player.position.x=nx;player.position.z=nz;player.rotation.y=Math.atan2(dx,dz);player.position.y=terrainHeight(nx,nz)}}
function updateCamera(){const target=new THREE.Vector3(player.position.x,player.position.y+1,player.position.z);const x=target.x+Math.sin(yaw)*cameraDistance,z=target.z+Math.cos(yaw)*cameraDistance;camera.position.set(x,target.y+cameraHeight,z);camera.lookAt(target.x,target.y+1.5,target.z)}
function animateWeather(dt){if(rain.visible){const arr=rainGeo.attributes.position.array;for(let i=0;i<rainCount;i++){arr[i*3+1]-=dt*18;if(arr[i*3+1]<0){arr[i*3]=player.position.x+(Math.random()-.5)*80;arr[i*3+1]=30;arr[i*3+2]=player.position.z+(Math.random()-.5)*80}}rainGeo.attributes.position.needsUpdate=true}if(snowflakes.visible){const arr=snowGeo.attributes.position.array;for(let i=0;i<400;i++){arr[i*3+1]-=dt*1.6;if(arr[i*3+1]<0){arr[i*3+1]=28;arr[i*3]=player.position.x+(Math.random()-.5)*80;arr[i*3+2]=player.position.z+(Math.random()-.5)*80}}snowGeo.attributes.position.needsUpdate=true}}
let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000);last=now;gameTime+=dt;advanceClock(dt);playerMove(dt);animateVillagers(gameTime,dt);moveTrain(commuter,dt);moveTrain(freightTrain,dt);animateWeather(dt);updateCamera();const target=nearest();const isNear=dist(player.position,target)<11;$('#prompt').style.display=isNear?'block':'none';if(isNear)$('#prompt').innerHTML=`${target.name} · нажмите <b>E</b>`;renderer.render(scene,camera)}requestAnimationFrame(frame);
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);
$('#sound').addEventListener('click',()=>{say('Звуки долины скоро прозвучат — пока наслаждайтесь тишиной');$('#sound').textContent='♪'});
